const cart = $('Set Cart Fields').first().json;
const geo = $('Geolocate IP Address').first().json;
const country = $('Determine Country from IP').first().json;
const rate = $json; // exchange-rate response

const usdRate = Number(rate.rate ?? 1);
const currency = country.currency || 'USD';
const symbol = country.currencySymbol || '';
const totalUsd = Number(cart.cart_total_usd || 0);
const totalLocal = Math.round(totalUsd * usdRate * 100) / 100;

// Region-aware greeting + coupon
let language = 'en';
let greeting = `Hi ${cart.first_name},`;
let coupon = 'COMEBACK10';
if (geo.isEU === true) {
  coupon = 'EU10';
} else if (['AR','BO','BR','CL','CO','EC','MX','PE','PY','UY','VE'].includes(geo.countryCode)) {
  language = 'es';
  greeting = `Hola ${cart.first_name},`;
  coupon = 'VOLVE10';
}

const totalLocalDisplay = `${symbol}${totalLocal.toLocaleString()} ${currency}`;

return [{
  json: {
    email: cart.email,
    first_name: cart.first_name,
    checkout_url: cart.checkout_url,
    country: country.name || geo.country,
    country_code: geo.countryCode,
    city: geo.city,
    currency,
    fx_rate: usdRate,
    cart_total_usd: totalUsd,
    cart_total_local: totalLocal,
    cart_total_local_display: totalLocalDisplay,
    language,
    greeting,
    coupon,
  }
}];
